// Code generated by testgen. DO NOT EDIT.
// The runtime every generated Playwright spec of a surface runs on. testgen copies this file,
// byte for byte, to <uitests>/generated/<surface>/runtime.gen.ts; nothing in it is specific to
// one surface, and an agent never edits it (a spec is declarative: it names an element of the
// UI design, an action, an observable, and the platform acts).
//
// Four things live here:
//   - installLatency: every same-origin API request of the page is held for a while, so a state
//     that only appears after the server answers is visibly slower than one the page shows at once;
//   - immediate: the timeout of an assertion about what the user sees the instant an action lands
//     (Layer A). It is short on purpose: a checkbox that flips only after the server answers
//     fails it under the injected latency;
//   - arrange / probe: a scenario's typed setup and its probes, executed over REST against the
//     running server, as the one process principal (X-Dev-Principal when AIARCH_DEV_PRINCIPAL is set);
//   - assertNever: the exhaustiveness check of every switch over a sum type.
import { expect, test } from '@playwright/test';
import type { Page, TestInfo } from '@playwright/test';

/** The timeout of an assertion about what the user sees the instant an action lands. */
export const immediate = { timeout: Number(process.env.AIARCH_UI_IMMEDIATE_MS ?? 250) };

/** The compile-time proof that a switch over a sum type handled every variant. */
export function assertNever(x: never): never {
  throw new Error('unreachable variant: ' + JSON.stringify(x));
}

/**
 * Holds every same-origin fetch/XHR request of the page for ms milliseconds before it reaches the
 * server. Install it before the first navigation. Documents, scripts and other origins are not
 * delayed: the page loads normally and only its API answers late.
 */
export async function installLatency(page: Page, ms: number): Promise<void> {
  await page.route('**/*', (route) => {
    const request = route.request();
    const type = request.resourceType();
    const sameOrigin = new URL(request.url()).origin === new URL(page.url()).origin;
    const proceed = (): void => {
      route.continue().catch(() => undefined); // the page may be gone by then
    };
    if (ms <= 0 || (type !== 'fetch' && type !== 'xhr') || !sameOrigin) {
      proceed();
      return;
    }
    setTimeout(proceed, ms);
  });
}

/** What a call is expected to answer: a result (JSON text) or an error. */
export type Expectation = {
  readonly result?: string;
  readonly errorExpected: boolean;
  readonly errorCode?: string;
};

/** One operation of a generated Manager route, with its arguments and expectation. */
export type ContractCall = {
  readonly verb: string;
  readonly path: string;
  readonly args: Readonly<Record<string, unknown>>;
  readonly expect: Expectation;
};

/** The typed setup of a scenario: exactly the four things the scenario host can arrange. */
export type ArrangeCall =
  | ({ readonly kind: 'contractCall' } & ContractCall)
  | { readonly kind: 'advanceClock'; readonly duration: string }
  | { readonly kind: 'failNext'; readonly component: string; readonly operation: string; readonly errorCode: string }
  | { readonly kind: 'seedResource'; readonly resource: string; readonly fixture: unknown };

/** Runs one arrange step; the switch is exhaustive over ArrangeCall. */
export async function arrange(testInfo: TestInfo, call: ArrangeCall): Promise<void> {
  switch (call.kind) {
    case 'contractCall':
      return callContract(testInfo, call, 'arrange');
    case 'advanceClock':
    case 'failNext':
    case 'seedResource':
      return skipUntilScenarioHost(call.kind);
    default:
      return assertNever(call);
  }
}

/** Runs one probe: a read-only operation observed after the step. */
export async function probe(testInfo: TestInfo, call: ContractCall): Promise<void> {
  return callContract(testInfo, call, 'probe');
}

function baseURL(testInfo: TestInfo): string {
  const base = testInfo.project.use.baseURL ?? process.env.PLAYWRIGHT_TEST_BASE_URL;
  if (!base) {
    throw new Error('no base URL: set PLAYWRIGHT_TEST_BASE_URL to the running server');
  }
  return base;
}

function headers(): Record<string, string> {
  const principal = process.env.AIARCH_DEV_PRINCIPAL;
  return principal ? { 'X-Dev-Principal': principal } : {};
}

/** The text of a query/path value: scalars as written, anything else as JSON. */
function wireText(value: unknown): string {
  return typeof value === 'object' && value !== null ? JSON.stringify(value) : String(value);
}

/**
 * Spells the arguments onto the route as the generated handler reads them: a {param} of the path
 * takes its value from the arguments, and the rest is the query of a GET or the JSON body of
 * anything else.
 */
function requestFor(base: string, call: ContractCall): { url: string; init: RequestInit } {
  const fields: Record<string, unknown> = { ...call.args };
  let path = call.path;
  for (const name of Object.keys(fields)) {
    const hole = '{' + name + '}';
    if (path.includes(hole)) {
      path = path.split(hole).join(encodeURIComponent(wireText(fields[name])));
      delete fields[name];
    }
  }
  const url = new URL(path, base);
  if (call.verb === 'GET') {
    for (const [name, value] of Object.entries(fields)) {
      url.searchParams.set(name, wireText(value));
    }
    return { url: url.toString(), init: { method: call.verb, headers: headers() } };
  }
  return {
    url: url.toString(),
    init: { method: call.verb, headers: { 'Content-Type': 'application/json', ...headers() }, body: JSON.stringify(fields) },
  };
}

/** The code a generated handler answers each Manager error kind with. */
const wireCodes: Readonly<Record<string, string>> = {
  ContractMisuse: 'contract_misuse',
  NotFound: 'not_found',
  Unauthorized: 'forbidden',
  FailedPrecondition: 'failed_precondition',
  Infrastructure: 'infrastructure',
};

function expectedValue(result: string): unknown {
  try {
    return JSON.parse(result);
  } catch {
    return result;
  }
}

async function callContract(testInfo: TestInfo, call: ContractCall, label: string): Promise<void> {
  const { url, init } = requestFor(baseURL(testInfo), call);
  const res = await fetch(url, init);
  const text = await res.text();
  const where = label + ' ' + call.verb + ' ' + call.path;
  if (call.expect.errorExpected) {
    expect(res.status, where + ' must be refused: ' + text).toBeGreaterThanOrEqual(400);
    const code = call.expect.errorCode;
    if (code) {
      const wire = wireCodes[code];
      expect(text.includes(code) || (wire !== undefined && text.includes(wire)), where + ' must answer ' + code + ': ' + text).toBe(true);
    }
    return;
  }
  expect(res.status, where + ' failed: ' + text).toBeLessThan(400);
  if (call.expect.result === undefined || call.expect.result === '') {
    return;
  }
  const actual: unknown = text === '' ? null : JSON.parse(text);
  const want = expectedValue(call.expect.result);
  if (typeof want === 'object' && want !== null) {
    expect(actual, where).toMatchObject(want as Record<string, unknown> | unknown[]);
  } else {
    expect(actual, where).toEqual(want);
  }
}

/**
 * A scenario that arranges the clock, a failing operation or a seeded resource needs the
 * local-profile /__scenariohost endpoint, which no generated server serves yet (the composed server
 * answers every unknown POST with 405, so the endpoint cannot be probed for: the scenario is skipped
 * up front, by name, instead of being run against state it did not set up). testgen emits the same
 * skip into the spec ahead of every action; this is the runtime's own answer if an arrange call of
 * one of these kinds reaches it. Plan 3 adds the endpoint and replaces both.
 */
export function skipUntilScenarioHost(kind: string): void {
  test.skip(true, 'arrange ' + kind + ' needs the local-profile /__scenariohost endpoint, which no generated server serves yet');
}
